import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';

const pkg = JSON.parse(readFileSync(new URL('../../package.json', import.meta.url), 'utf8'));
assert.ok(['12.0.0', '^12.0.0'].includes(pkg.devDependencies.c8), pkg.devDependencies.c8);
const lock = JSON.parse(readFileSync(new URL('../../package-lock.json', import.meta.url), 'utf8'));
assert.equal(lock.packages['node_modules/c8'].version, '12.0.0');
assert.ok(['12.0.0', '^12.0.0'].includes(lock.packages[''].devDependencies.c8), lock.packages[''].devDependencies.c8);

console.log('visible check passed');

import * as chai from '../../index.js';
import assert from 'node:assert/strict';

chai.expect([[1], [2]]).to.deep.contain.oneOf([[1], [2]]);
chai.expect([[3], [4]]).to.not.deep.contain.oneOf([[1], [2]]);
assert.throws(() => chai.expect([[1]]).to.deep.contain.oneOf([[2]]));
chai.expect([1, 2]).to.contain.oneOf([4, 2, 5]);
chai.expect([[1]]).to.not.contain.oneOf([[1]]);

console.log('visible check passed');
